#!/usr/bin/env node
// Generated by npm run build from checks/test-change-review.mjs. Edit that file, not this one.
// Test change review at the pull request (docs/specs/test-change-review.md, AC-8 to AC-10). Builds
// what the test-change-reviewer agent works from, and formats the comment it posts.
//
// The input has: each test case the change modifies in existing test files, with the classifier's
// findings and the evidence from running it on head and against base (test-change-evidence.mjs);
// the spec criteria those tests cite or that unlock their files, with the criterion text at base and
// head and the spec's status; the unlocks entries naming the changed files; the diff of the changed
// test files; and whether the project's specs need an approver (rfr-process `stages.specs`). It holds
// nothing from the session that made the change, so the reviewer judges the change on its own.
//
// Usage:
//   node checks/test-change-review.mjs input <base> [head]       JSON input for the reviewer
//   node checks/test-change-review.mjs comment <decision.json>   the comment, from the reviewer's decision
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { collectEvidence } from './test-change-evidence.mjs';
import { isTestOrBaseline } from './lib/test-paths.mjs';

function git(cwd, args) {
  const r = spawnSync('git', ['-c', 'core.quotepath=off', ...args], { cwd, encoding: 'utf8', maxBuffer: 1 << 28 });
  return r.status === 0 ? r.stdout : null;
}

const frontMatter = text => /^---\r?\n([\s\S]*?)\r?\n---/.exec(text ?? '')?.[1] ?? '';
const statusOf = text => /^status:\s*(\S+)/m.exec(frontMatter(text))?.[1] ?? null;

// | AC-n | criterion | verified by | -> Map(id -> criterion text)
function criteriaOf(text) {
  const map = new Map();
  for (const m of (text ?? '').matchAll(/^\|\s*(AC-\d+)\s*\|(.*)\|[^|\n]*\|\s*$/gm)) map.set(m[1], m[2].trim());
  return map;
}

function unlocksOf(text) {
  const lines = frontMatter(text).split(/\r?\n/);
  const at = lines.findIndex(l => /^unlocks:\s*$/.test(l));
  if (at === -1) return [];
  const entries = [];
  for (const l of lines.slice(at + 1)) {
    if (!/^\s/.test(l)) break;
    const m = /^\s+-\s+(.+?):\s+(.*)$/.exec(l);
    if (m) entries.push({ file: m[1].replace(/\s+\(new\)$/, '').trim(), reason: m[2] });
  }
  return entries;
}

function specsGated(root, head) {
  const yml = git(root, ['show', `${head}:docs/product/process.yml`]);
  if (yml === null) return null;
  // stages: ... specs: [a, b] (or a block list) means specs need an approver.
  const m = /^\s+specs:\s*(.*)$/m.exec(yml);
  if (!m) return false;
  return m[1].trim() !== '' && m[1].trim() !== '[]';
}

export async function buildReviewInput({ root, base, head = 'HEAD', specsDir = 'docs/specs' }) {
  const evidence = await collectEvidence({ root, base, head });
  const headSha = evidence.head;
  const baseSha = evidence.base;
  const changedTests = (git(root, ['diff', '--name-status', '--no-renames', baseSha, headSha]) ?? '').trim().split('\n').filter(Boolean)
    .map(l => l.split('\t')).filter(([status, file]) => status[0] !== 'A' && isTestOrBaseline(file)).map(([, file]) => file);
  const diff = changedTests.length ? git(root, ['diff', baseSha, headSha, '--', ...changedTests]) ?? '' : '';

  const specFiles = (git(root, ['ls-tree', '--name-only', headSha, `${specsDir}/`]) ?? '').trim().split('\n').filter(f => f.endsWith('.md'));
  const unlocks = [];
  const criteria = [];
  const cited = new Map();
  for (const c of [...evidence.cases, ...evidence.notRun.flatMap(n => n.cases.map(key => ({ key })))]) {
    for (const m of c.key.matchAll(/([\w-]+)#(AC-\d+)/g)) {
      const spec = `${specsDir}/${m[1]}.md`;
      const id = `${spec} ${m[2]}`;
      if (!cited.has(id)) cited.set(id, { spec, id: m[2], citedBy: [] });
      if (!cited.get(id).citedBy.includes(c.key)) cited.get(id).citedBy.push(c.key);
    }
  }
  for (const spec of specFiles) {
    const after = git(root, ['show', `${headSha}:${spec}`]);
    for (const u of unlocksOf(after)) {
      if (!changedTests.includes(u.file)) continue;
      const ids = [...u.reason.matchAll(/\bAC-\d+\b/g)].map(m => m[0]);
      unlocks.push({ spec, file: u.file, reason: u.reason, criteria: ids });
      for (const idText of ids) {
        const id = `${spec} ${idText}`;
        if (!cited.has(id)) cited.set(id, { spec, id: idText, citedBy: [] });
      }
    }
  }
  for (const { spec, id, citedBy } of cited.values()) {
    const beforeText = git(root, ['show', `${baseSha}:${spec}`]);
    const afterText = git(root, ['show', `${headSha}:${spec}`]);
    const before = criteriaOf(beforeText).get(id) ?? null;
    const after = criteriaOf(afterText).get(id) ?? null;
    criteria.push({ spec, id, status: statusOf(afterText), before, after, changed: before !== after, citedBy });
  }
  return {
    base: baseSha, head: headSha, cases: evidence.cases, notRun: evidence.notRun, note: evidence.note,
    criteria, unlocks, specsGated: specsGated(root, headSha), diff,
  };
}

const cell = s => String(s ?? '').replace(/\r?\n/g, ' ').replace(/\|/g, '\\|').trim();

function evidenceText(c) {
  const head = c.head === 'pass' ? 'passes on head' : c.head === 'fail' ? 'fails on head' : 'not run on head';
  const base = c.base === 'fail' ? 'fails on base' : c.base === 'pass' ? 'passes on base' : 'not run on base';
  const sabotage = c.sabotage === 'fails' ? 'fails when the behaviour is broken'
    : c.sabotage === 'passes' ? 'still passes when the behaviour is broken' : 'not broken on purpose';
  return `${head}, ${base}, ${sabotage}`;
}

// The reviewer's comment for one head commit. decision is 'approve' or 'refer'; labelAdded says
// whether review-pr added the tests-reviewed label (it does on a pull request since the eval in AC-11
// passed; a review of a local branch has no pull request to label).
export function formatReviewComment({ head, decision, labelAdded = false, cases = [], summary = '' }) {
  const short = String(head).slice(0, 7);
  const lines = [`<!-- rfr-test-change-review head=${head} -->`];
  lines.push(decision === 'approve' ? `### Test change review: Approved` : `### Test change review: Referred to the lead`);
  lines.push('', `On \`${short}\`.${summary ? ` ${cell(summary)}` : ''}`, '');
  lines.push('| Test | Finding | Reason | Evidence | Verdict |', '|---|---|---|---|---|');
  for (const c of cases) {
    const verdict = c.missing?.length ? `missing: ${c.missing.join('; ')}` : 'ok';
    lines.push(`| \`${cell(c.file)}:${c.line}\` ${cell(c.key)} | ${cell(c.kinds?.join(', ') || 'none')} | ${cell(c.reason || 'none recorded')} | ${cell(evidenceText(c))} | ${cell(verdict)} |`);
  }
  lines.push('');
  if (decision === 'approve') {
    lines.push(labelAdded
      ? 'Every changed test has an approved reason, and the evidence holds, so the reviewer added the `tests-reviewed` label.'
      : 'Every changed test has an approved reason, and the evidence holds, so the change is ready for the `tests-reviewed` label. No label was added, because this review had no pull request to label.');
  } else {
    const missing = [...new Set(cases.flatMap(c => c.missing ?? []))];
    lines.push('What is missing:', ...missing.map(m => `- ${m}`), '', 'No label was added; the lead decides.');
  }
  lines.push('', 'A later push makes this review stale, and the reviewer runs again.');
  return lines.join('\n');
}

async function main() {
  const [mode, ...rest] = process.argv.slice(2);
  if (mode === 'input' && rest[0]) {
    console.log(JSON.stringify(await buildReviewInput({ root: process.cwd(), base: rest[0], head: rest[1] ?? 'HEAD' }), null, 2));
  } else if (mode === 'comment' && rest[0]) {
    console.log(formatReviewComment(JSON.parse(fs.readFileSync(rest[0], 'utf8'))));
  } else {
    console.error('Usage: node checks/test-change-review.mjs input <base> [head] | comment <decision.json>');
    process.exit(2);
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
